  type        = bool
  default     = false
}

variable "kms_key_arn" {
  description = "ARN of the KMS key that encrypts the bucket. Required. Applying this module rebuilds the bucket."
  type        = string
}

latest.outputs.tf:
output "bucket_id" {
  description = "ID of the created S3 bucket."
  value       = aws_s3_bucket.this.id
}

